// Verificar com gov.br (bipe-chat/bipe#544, spec product/screens/govbr-verify.json). Reference rules for
// BipeGovbrFlow (BipeKit) and BipeGovbrFlow.kt (libraries/bipe). test-vectors/govbr-verify.json comes from here.

export const GOVBR_PHASES = ["ready", "preparing", "waitingForSignature", "checking", "verified", "rejected", "failed"];
export const GOVBR_REASONS = ["not_signed", "not_govbr", "wrong_document", "expired", "cpf_in_use", "changed_after_signing"];

// What the app does with a PDF that arrives (share sheet, open with, or the "Já assinei" picker).
// upload: send it with PUT .../document. noOpenVerification: show bipe_govbr_no_open_verification and do not upload.
// ignore: a check runs; the file is dropped without a message. notSigned: empty or bigger than maxDocumentBytes,
// shown as the reason not_signed without an upload.
export function govbrIncoming(phase, byteCount, maxDocumentBytes) {
  if (!GOVBR_PHASES.includes(phase)) throw new Error(`govbr: unknown phase ${phase}`);
  if (phase === "checking") return "ignore";
  if (phase !== "waitingForSignature") return "noOpenVerification";
  if (byteCount <= 0 || byteCount > maxDocumentBytes) return "notSigned";
  return "upload";
}

// The phase after a VerificationStatus answer of PUT .../document. A reason the app does not know fails closed.
export function govbrResult(state, reason) {
  switch (state) {
    case "verified":
      return { phase: "verified" };
    case "rejected":
      if (reason == null) return { phase: "rejected", reason: "expired" };
      return GOVBR_REASONS.includes(reason) ? { phase: "rejected", reason } : { phase: "failed" };
    case "expired":
      return { phase: "rejected", reason: "expired" };
    default:
      return { phase: "failed" };
  }
}
